#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QJsonArray>
#include <QTemporaryDir>
#include <cmath>
#include <iostream>
#include <numbers>
#include <stdexcept>
void check(bool ok,const QString& why){if(!ok)throw std::runtime_error(why.toStdString());}
QJsonObject row(const QJsonObject& s,const char* key,const QString& id){for(const auto& v:s["parameters"].toObject()[key].toArray())if(v.toObject()["id"]==id)return v.toObject();return {};}
void verify(const QJsonObject& s){const auto g=s["parameters"].toObject()["patternGroups"].toArray().first().toObject(),seed=row(s,"entities",g["sourceEntityId"].toString()),source=row(s,"points",seed["centerPointId"].toString()),origin=row(s,"points",g["centerPointId"].toString());const double u=origin["uMm"].toDouble(),v=origin["vMm"].toDouble(),x=source["uMm"].toDouble()-u,y=source["vMm"].toDouble()-v;for(const auto& r:g["instances"].toArray()){const auto instance=r.toObject(),circle=row(s,"entities",instance["entityId"].toString()),point=row(s,"points",instance["pointId"].toString());const double a=g["totalAngleDeg"].toDouble()*std::numbers::pi/180*instance["k"].toInt()/(g["quantity"].toInt()-(g["mode"]=="full" ? 0 : 1));check(std::abs(point["uMm"].toDouble()-u-x*std::cos(a)+y*std::sin(a))<1e-6 && std::abs(point["vMm"].toDouble()-v-x*std::sin(a)-y*std::cos(a))<1e-6,"Exact circular indexed center");check(circle["radiusMm"]==seed["radiusMm"],"Derived radius");}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument doc;auto s=SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY");auto added=SketchGeometry::addStandalonePoint(s,{{"uMm",25},{"vMm",25}});check(added.ok,added.error);s=added.feature;const auto centerEntity=s["parameters"].toObject()["entities"].toArray().first().toObject();const auto centerId=centerEntity["pointId"].toString();
 s=SketchGeometry::addCircle(s,{{"centerUMm",37},{"centerVMm",25},{"diameterMm",3}});const auto seed=s["parameters"].toObject()["entities"].toArray().last().toObject();auto result=SketchGeometry::addDimension(s,{{"kind","radius"},{"entityId",seed["id"]},{"valueMm",1.5}});check(result.ok,result.error);s=result.feature;const auto radiusId=s["parameters"].toObject()["dimensions"].toArray().last().toObject().value("id");const auto baseline=SketchGeometry::solveDraft(s);check(baseline.ok,baseline.error);
 QJsonObject args{{"sourceEntityId",seed["id"]},{"centerPointId",centerId},{"quantity",6},{"mode","full"},{"totalAngleDeg",360}};result=SketchGeometry::circularPattern(s,args);check(result.ok,result.error);s=result.feature;const auto full=s;const auto group=s["parameters"].toObject()["patternGroups"].toArray().first().toObject();check(result.diagnostics["dof"]==baseline.diagnostics["dof"],"Circular copies add no independent DOF");check(row(s,"entities",seed["id"].toString())==seed,"Original circle unchanged");verify(s);check(SketchGeometry::evaluateFeature(s).profiles.size()==6,"Full produces six profiles");
 args["groupId"]=group["id"];args["quantity"]=8;result=SketchGeometry::circularPattern(s,args);check(result.ok,result.error);s=result.feature;verify(s);check(s["parameters"].toObject()["patternGroups"].toArray().first().toObject()["instances"].toArray().first()==group["instances"].toArray().first(),"Full count surviving IDs stable");
 args["quantity"]=4;args["mode"]="angle";args["totalAngleDeg"]=120;result=SketchGeometry::circularPattern(s,args);check(result.ok,result.error);s=result.feature;verify(s);const auto angle120=s;args["totalAngleDeg"]=150;result=SketchGeometry::circularPattern(s,args);check(result.ok,result.error);s=result.feature;verify(s);const auto angle150=s;
 for(const auto& bad:QJsonArray{QJsonObject{{"quantity",2.5}},QJsonObject{{"quantity",1}},QJsonObject{{"centerPointId",seed["centerPointId"]}},QJsonObject{{"centerPointId",CadDocument::newId()}},QJsonObject{{"totalAngleDeg",0}},QJsonObject{{"totalAngleDeg",360}},QJsonObject{{"totalAngleDeg",2}}}){auto input=args;const auto b=bad.toObject();for(auto it=b.begin();it!=b.end();++it)input[it.key()]=it.value();const auto refusal=SketchGeometry::circularPattern(s,input);check(!refusal.ok && refusal.feature==s,"Invalid circular input atomic");}
 const auto instance=group["instances"].toArray().first().toObject();for(const auto& id:QJsonArray{seed["id"],centerEntity["id"],instance["entityId"]}){const auto refusal=SketchGeometry::deleteEntities(s,QJsonArray{id},{});check(!refusal.ok && refusal.feature==s,"Circular owner Delete atomic");}
 result=SketchGeometry::movePoint(s,{{"pointId",instance["pointId"]},{"uMm",4},{"vMm",3}});check(!result.ok && result.feature==s,"Derived drag refuses");result=SketchGeometry::toggleFixed(s,{{"entityIds",QJsonArray{instance["entityId"]}}});check(!result.ok && result.feature==s,"Derived constraint refuses");
 result=SketchGeometry::movePoint(s,{{"pointId",seed["centerPointId"]},{"uMm",25},{"vMm",25}});check(!result.ok && result.feature==s,"Source at center refuses");
 result=SketchGeometry::updateDimension(s,{{"dimensionId",radiusId},{"valueMm",2}});check(result.ok,result.error);s=result.feature;result=SketchGeometry::movePoint(s,{{"pointId",centerId},{"uMm",26},{"vMm",24}});check(result.ok,result.error);s=result.feature;result=SketchGeometry::movePoint(s,{{"pointId",seed["centerPointId"]},{"uMm",38},{"vMm",26}});check(result.ok,result.error);s=result.feature;verify(s);
 for(const auto& state:QJsonArray{full,angle120,angle150,s}){const auto error=doc.commit(SketchGeometry::replaceFeature(doc.authored(),state.toObject()),"Circular Pattern");check(error.isEmpty(),error);}const auto authored=doc.authored();doc.history().undo();check(SketchGeometry::findFeature(doc.authored(),s["id"].toString())==angle150,"Distinct circular edit Undo");doc.history().redo();check(doc.authored()==authored,"Exact circular Redo");QTemporaryDir dir;const auto path=dir.filePath("circular.alloy");check(doc.save(path).isEmpty(),"Circular save");CadDocument opened;check(opened.open(path).isEmpty() && opened.authored()==authored,"Exact circular authored reopen");std::cout<<"CIRCULAR_SKETCH_PATTERN_CORE_OK\n";return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
